questionvariables.text:
r(x):=rand_with_prohib(-x,x,[0]);
randconst:r(5);
r2:r(5);
tinv:1/t;
lindenomwithconst: 1/(t+randconst);
trigp:[-tan(t),cot(t)];
randrationallin:(r(5)*t+r(5));
randrationalp:diff(randrationallin,t)/randrationallin;

randlinear:r2*t+randconst;
gaussian:%e^(randconst*t^2);
simplebyparts:[r2*sin(randconst*t),r2*cos(randconst*t),r2*%e^(randconst*t)];

pqpairs:append([[tinv,gaussian],[randlinear,r2*t*%e^(-randconst*t)],[randlinear,randconst*%e^(-r2*t^2/2+r(3)*t+r(4))],[randrationalp,randlinear]],maplist(lambda([x],[lindenomwithconst,x]),simplebyparts),maplist(lambda([x],[x,randlinear]),trigp));
[p,q]:rand(pqpairs);

/* NB */
logabs:false;

/* This isn't pretty, but I couldn't find a way to get maxima to display the equations the way I wanted without doing this */
denp:denom(trigsimp(p));
f0:x1 + p*x0 = q*xn;
f1:x1 + p*x0 - q*xn = 0;
f2:x1 = q*xn - p*x0;
f3:x1 - q*xn = - p*x0;
f4:ev(trigsimp(denp*f0),nouns,fullratsimp);
f5:ev(trigsimp(denp*f1),nouns,fullratsimp);
f6:ev(trigsimp(denp*f2),nouns,fullratsimp);
f7:ev(trigsimp(denp*f3),nouns,fullratsimp);

/* ff is the equation to be displayed in LaTeX, with derivatives represented as primes, f is the internal maxima expression */
n:rand([-2,2,4]);
ff:rand([f0,f1,f2,f3,f4,f5,f6,f7]);
fft:at(ff,[x1=(1-n)*x1]);
f:at(ff,[x1='diff(x(t),t,1),x0=x(t),xn=1]);
ft:at(ff,[x1=(1-n)*'diff(x(t),t,1),x0=x(t),xn=(x(t))^n]);

texput(x1,"x^{\\prime}(t)");
texput(x0,"x(t)");
texput(xn,sconcat("x^{",n,"}(t)"));

IF:%e^(integrate(p,t));
tat:ev((integrate(IF*q,t)+C)/IF,nouns,fullratsimp);
ta:rhs(last(solve(x^(1-n)=tat,x)));

r(x):=rand_with_prohib(-x,x,[0]);

a:r(5);
Phi1:y*log(x)+r(4)*x^2-r(4)*y;
Phi2:expand((y+x)^3)+(r(5)*x+r(5));
Phi3:x^2*%e^(y+a)+abs(r(3))*%e^(y+a)-abs(r(5))+r(5)*x;

[Phi,initvalx,initvaly]:rand([[Phi1,1,r(5)],[Phi2,1,abs(r(5))],[Phi3,0,r(5)]]);

Phix:diff(Phi,x);
Phiy:diff(Phi,y);

/* NB */
logabs:false;

/* ff is the equation to be displayed in LaTeX, with derivatives represented as primes, f is the internal maxima expression */
ordergreat(dx,dy,x,y);
f0:Phiy*y1+Phix=0;
f1:Phiy*y1=-Phix;
f2:Phiy*dy=-Phix*dx;
f3:Phiy*dy+Phix*dx=0;
ff:rand([f1,f2,f3]);
f:at(at(f0,[y=y0]),[y1='diff(y(x),x,1),y0=y(x)]);

texput(y1,"y^{\\prime}(x)");

ta:rhs(last(solve(Phi=c,y)));

sol:solve(ev(ta,x=initvalx)=initvaly,[c]);
ta2:at(ta,sol[1]);

r(x):=rand_with_prohib(-x,x,[0]);
randconst:r(5);
r2:r(5);
tinv:1/t;
lindenomwithconst: 1/(t+randconst);
trigp:[-tan(t),cot(t)];
randrationallin:(r(5)*t+r(5));
randrationalp:diff(randrationallin,t)/randrationallin;

randlinear:r2*t+randconst;
gaussian:%e^(randconst*t^2);
simplebyparts:[r2*sin(randconst*t),r2*cos(randconst*t),r2*%e^(randconst*t)];

pqpairs:append([[tinv,gaussian],[randlinear,r2*t*%e^(-randconst*t)],[randlinear,randconst*%e^(-r2*t^2/2+r(3)*t+r(4))],[randrationalp,randlinear]],maplist(lambda([x],[lindenomwithconst,x]),simplebyparts),maplist(lambda([x],[x,randlinear]),trigp));
[p,q]:rand(pqpairs);

/* NB */
logabs:false;

/* This isn't pretty, but I couldn't find a way to get maxima to display the equations the way I wanted without doing this */
denp: denom(p);
f0:x1 + p*x0 = q;
f1:x1 + p*x0 - q = 0;
f2:x1 = q - p*x0;
f3:x1 - q = - p*x0;
f4:ev(trigsimp(denp*f0),nouns,fullratsimp);
f5:ev(trigsimp(denp*f1),nouns,fullratsimp);
f6:ev(trigsimp(denp*f2),nouns,fullratsimp);
f7:ev(trigsimp(denp*f3),nouns,fullratsimp);

/* ff is the equation to be displayed in LaTeX, with derivatives represented as primes, f is the internal maxima expression */
ff:rand([f0,f1,f2,f3,f4,f5,f6,f7]);
f:at(ff,[x1='diff(x(t),t,1),x0=x(t)]);

texput(x1,"x^{\\prime}(t)");
texput(x0,"x(t)");

IF:%e^(integrate(p,t));
ta:ev((integrate(IF*q,t)+C)/IF,nouns,fullratsimp);

r(x):=rand_with_prohib(-x,x,[0]);
randconst:r(5);
r2:r(5);
tinv:1/t;
lindenomwithconst: 1/(t+randconst);
trigp:[-tan(t),cot(t)];
randrationallin:(r(5)*t+r(5));
randrationalp:diff(randrationallin,t)/randrationallin;

randlinear:r2*t+randconst;
gaussian:%e^(randconst*t^2);
simplebyparts:[r2*sin(randconst*t),r2*cos(randconst*t),r2*%e^(randconst*t)];

pqpairs:append([[tinv,gaussian],[randlinear,r2*t*%e^(-randconst*t)],[randlinear,randconst*%e^(-r2*t^2/2+r(3)*t+r(4))],[randrationalp,randlinear]],maplist(lambda([x],[lindenomwithconst,x]),simplebyparts),maplist(lambda([x],[x,randlinear]),trigp));
[p,q]:rand(pqpairs);

initvalt:if p=1/t then 1 else (if p = cot(t) then %pi/2 else 0);
initvalx:r(10);

/* NB */
logabs:false;

/* This isn't pretty, but I couldn't find a way to get maxima to display the equations the way I wanted without doing this */
denp: denom(p);
f0:x1 + p*x0 = q;
f1:x1 + p*x0 - q = 0;
f2:x1 = q - p*x0;
f3:x1 - q = - p*x0;
f4:ev(trigsimp(denp*f0),nouns,fullratsimp);
f5:ev(trigsimp(denp*f1),nouns,fullratsimp);
f6:ev(trigsimp(denp*f2),nouns,fullratsimp);
f7:ev(trigsimp(denp*f3),nouns,fullratsimp);

/* ff is the equation to be displayed in LaTeX, with derivatives represented as primes, f is the internal maxima expression */
ff:rand([f0,f1,f2,f3,f4,f5,f6,f7]);
f:at(ff,[x1='diff(x(t),t,1),x0=x(t)]);

texput(x1,"x^{\\prime}(t)");
texput(x0,"x(t)");

IF:%e^(integrate(p,t));
ta:ev((integrate(IF*q,t)+C)/IF,nouns,fullratsimp);

sol:solve(ev(ta,t=initvalt)=initvalx,[C]);
ta2:at(ta,sol[1]);

r(x):=rand_with_prohib(-x,x,[0]);
randconst:r(5);
r2:r(5);
r3:rand_with_step(-3,-1,1);
rpos:rand_with_step(1,5,1);
tinv:1/t;

randlinear(var):=randconst*var+r(5);
randlinear2(var):=(signum(randconst)*signum(r2))*r2*var+r(5);
randlinearstrict(var):=(r2*var);
gaussian(var):=%e^(rpos*var^2);
lindenomwithconst(var):= 1/(rand_with_step(1,3,1)*var+rand_with_step(0,5,1));
quaddenomwithconst(var):= var/(rand_with_step(1,3,1)*var^2+rand_with_step(0,5,1));
randmonomial(var):=-var^r3;
randmonomial2(var):=(r4:rand_with_prohib(-3,1,[0]),if is(equal(r3,3)) and (is(equal(r4,1)) or is(equal(r4,-1))) then (var^r3) else (-var^r3));
randexponential(var):=(r4:r(5),signum(r4)*signum(randconst)*%e^(r4*var));
randpartialfrac(var):=(alp:r(5),r:r2,alp/(var^2-(2*r+1)*var+(r^2+r)));

pqpairs:[[lindenomwithconst(x),lindenomwithconst(t)],[randmonomial(x),randmonomial(t)],[randexponential(x),randlinear(t)],[randlinear(x),randlinear2(t)],[lindenomwithconst(x),randlinearstrict(t)],[quaddenomwithconst(x),randlinearstrict(t)],[x*gaussian(x),signum(r2)*randlinearstrict(t)],[1/(x),randpartialfrac(t)]];
[p,q]:rand(pqpairs);

/* NB */
logabs:false;
logconcoeffp:'logconfun;
logconfun(m):=integerp(m) or ratnump(m);

/* This isn't pretty, but I couldn't find a way to get maxima to display the equations the way I wanted without doing this */
denp: denom(p);
f0:p*x1=q;
f1:p*x1 - q = 0;
f2:x1 = (q/p);
f3:x1 - (q/p) = 0;

/* ff is the equation to be displayed in LaTeX, with derivatives represented as primes, f is the internal maxima expression */
ff:rand([f0,f1,f2,f3]);

f:at(ff,[x1='diff(x,t,1)]);

texput(x1,"x^{\\prime}");

rootproblem:not freeof(x^2,integrate(p,x));
rootprobstring:if rootproblem then ", where \\(x(t)>0\\)" else "";
ta:rhs(ev(last(solve(integrate(p,x)=integrate(q,t)+c,x)),fullratsimp,nouns,logsimp,logcontract,factor));
